def trace(input_data):
    sess = TraceSession('Backtracking Permutations', input_data,
        pseudocode=['Fix each position by swapping and recurse', 'Undo swap to backtrack'])
    nums = input_data['nums']
    arr = sess.array('nums', nums)
    n = len(nums)
    answer = []
    frames = sess.tree('call_stack')
    def backtrack(first):
        with frames.frame(f'backtrack({first})'):
            if first == n:
                perm = arr.to_list()
                answer.append(perm)
                sess.note(f'Found permutation: {perm}')
                return
            for i in range(first, n):
                arr.swap(first, i, reason=f'Swap {arr.to_list()[first]} and {arr.to_list()[i]} to fix position {first}')
                backtrack(first + 1)
                arr.swap(first, i, reason=f'Backtrack: undo swap at position {first}')
    backtrack(0)
    answer.sort()
    sess.result(answer)
    trace = sess.to_trace()
    for event in trace['events']:
        op = event.get('op')
        targets = [t.get('id', '') for t in event.get('targets', [])]
        reason = event.get('reason', '')
        if op == 'create' and 'nums' in targets:
            event['code_line'] = 2
        elif op == 'create' and 'call_stack' in targets:
            event['code_line'] = 2
        elif op == 'enter' and ('call_stack' in targets or 'frame' in targets):
            event['code_line'] = 9
        elif op == 'exit' and ('call_stack' in targets or 'frame' in targets):
            event['code_line'] = 9
        elif op == 'note' and 'Found permutation' in reason:
            event['code_line'] = 5
        elif op == 'swap' and 'to fix position' in reason:
            event['code_line'] = 8
        elif op == 'swap' and 'undo swap' in reason:
            event['code_line'] = 10
        elif op == 'answer':
            event['code_line'] = 13
        else:
            event['code_line'] = 9
    return trace

