def solve(input_data):
    nums = sorted(input_data['nums'])
    res = []
    while True:
        res.append(nums[:])
        k = -1
        for i in range(len(nums) - 2, -1, -1):
            if nums[i] < nums[i + 1]:
                k = i
                break
        if k == -1:
            break
        l = -1
        for i in range(len(nums) - 1, k, -1):
            if nums[k] < nums[i]:
                l = i
                break
        nums[k], nums[l] = nums[l], nums[k]
        nums[k + 1:] = reversed(nums[k + 1:])
    return res
